import numpy as np
import pandas as pd

def _returns():
    df = pd.read_csv('futures-daily.csv')
    return np.log(df['close']).diff().dropna()

def lag_corr(k):
    r = _returns()
    return float(r.corr(r.shift(k)))

def lag_t(k):
    n = len(_returns()) - k
    c = lag_corr(k)
    return float(c * np.sqrt(n - 2) / np.sqrt(1 - c * c))
